<template>
  <article class="asset-card">
    <div class="asset-overview"><div class="asset-heading"><span class="asset-icon"><i :class="asset.category === 'ENTITLEMENT' ? 'el-icon-mic' : 'el-icon-tickets'" /></span><div><h3>{{ asset.name || asset.product || '供应商资源包' }}</h3><p>{{ product(asset) }}<span v-if="primary.isShareable === true"> · 可共享</span><span v-else-if="primary.isShareable === false"> · 不可共享</span></p></div></div><el-tag size="small" :type="state(asset) === 'current' ? 'info' : 'warning'">{{ state(asset) === 'expired' ? '已到期' : state(asset) === 'exhausted' ? '已耗尽' : label(primary.status) === '—' ? '状态未提供' : label(primary.status) }}</el-tag></div>
    <div v-if="asset.category !== 'ENTITLEMENT'" class="asset-quantities"><div><span>官方剩余额度</span><strong>{{ quantity(primary.availableAmount, primary.unit) }}</strong></div><div v-if="present(primary.totalAmount)"><span>官方总额度</span><strong>{{ quantity(primary.totalAmount, primary.unit) }}</strong></div><div v-if="present(primary.purchasedAmount)"><span>供应商购买量</span><strong>{{ quantity(primary.purchasedAmount, primary.unit) }}</strong></div><div v-if="present(primary.currentUsage)"><span>供应商当前用量</span><strong>{{ quantity(primary.currentUsage, primary.unit) }}</strong></div></div>
    <p v-else class="entitlement-note">音色或功能使用权益，不计入字符、时长等可抵扣额度。</p>
    <div class="asset-meta"><span><i class="el-icon-time" /> {{ primary.expiryTime ? '到期 ' + time(primary.expiryTime) : '到期时间未提供' }}</span><span>{{ observations.length }} 个官方来源 · 不叠加额度</span></div>
    <p v-for="(alert, index) in alerts" :key="index" class="asset-alert"><i class="el-icon-warning-outline" /> {{ alert.message }}</p>
    <details class="asset-details"><summary>查看官方来源与适用条件 <i class="el-icon-arrow-down" /></summary><div class="asset-evidence"><p class="evidence-note">当前快照不能证明消费发生时的包状态。是否实际抵扣，仍以供应商抵扣凭证为准。</p><dl><dt>购买实例</dt><dd>{{ asset.instanceNo || '供应商未返回，不能用于实例归属' }}</dd><dt>抵扣关联</dt><dd>尚未取得该笔消费与此资源包的抵扣证据</dd></dl><section v-for="(row, index) in observations" :key="index" class="observation"><div class="observation-heading"><strong>{{ label(row.sourceProvider || row.provider) }}</strong><span>{{ time(row.lastSyncedAt) }}</span></div><p v-if="row.sourceStatus === 'SYNC_FAILED'" class="asset-alert">最近同步失败，以下为此前成功快照。</p><dl><dt>官方剩余</dt><dd>{{ asset.category === 'ENTITLEMENT' ? '不适用' : quantity(row.availableAmount, row.unit) }}</dd><dt>总额度 / 购买量</dt><dd>{{ quantity(row.totalAmount, row.unit) }} / {{ quantity(row.purchasedAmount, row.unit) }}</dd><dt>供应商当前用量</dt><dd>{{ quantity(row.currentUsage, row.unit) }}</dd><dt>共享 / 重置周期</dt><dd>{{ row.isShareable === true ? '可共享' : row.isShareable === false ? '不可共享' : '共享条件未提供' }} / {{ label(row.resetPeriod) }}</dd><dt>有效期</dt><dd>{{ time(row.effectiveTime) }} 至 {{ time(row.expiryTime) }}</dd></dl></section></div></details>
  </article>
</template>
<script>
import { billingLabel, billingTime, decimalText } from '@/utils/billing';
import { assetObservations, primaryObservation, assetProduct, assetState } from '@/utils/billingAssets';
export default {
  props: { asset: { type: Object, required: true } },
  computed: { observations() { return assetObservations(this.asset); }, primary() { return primaryObservation(this.asset); }, alerts() { return (this.asset.alerts || []).length ? this.asset.alerts : this.primary.alerts || []; } },
  methods: { label: billingLabel, time: billingTime, product: assetProduct, state: assetState, present(value) { return value !== null && value !== undefined && value !== ''; }, quantity(value, unit) { if (!this.present(value)) return '供应商未提供'; const number = decimalText(value); return number === '—' ? billingLabel(value) : `${number} ${unit ? billingLabel(unit) : '（单位未提供）'}`; } }
};
</script>
